let statusAnfrage = null; // ein Abruf je Seitenaufruf
function versandStatusLaden() {
  statusAnfrage ||= fetch("/api/rechner/bericht", { headers: { Accept: "application/json" } })
    .then((r) => r.json().catch(() => ({})))
    .then((j) => (j && j.ok && j.versand === true ? "an" : "aus"))
    .catch(() => {
