        ? [
            kz("Pacht pro Jahr", `${fmtEur(r.pachtJahr.min)} – ${fmtEur(r.pachtJahr.max)}`, `${fmt(r.pachtJahr.min / e.ha)}–${fmt(r.pachtJahr.max / e.ha)} €/ha`),
