export const RECHNER_IDS = Object.freeze(Object.keys(RECHNER));

/** Rechner aus der Positivliste oder 422 */
export function rechnerVon(id) {
  if (typeof id !== "string" || !Object.hasOwn(RECHNER, id)) throw new PlattformFehler(422, "Für diesen Rechner gibt es keinen Bericht.", "rechner");
  return RECHNER[id];
}

/** Land DE | AT | CH oder 422 */
export function landPruefen(land) {
  const l = typeof land === "string" ? land.trim().toUpperCase() : "";
  if (!LAENDER.includes(l)) throw new PlattformFehler(422, "Bitte ein Land angeben (DE, AT oder CH).", "land");
  return l;
}

/** Stabile JSON-Darstellung (sortierte Schlüssel) – Grundlage der Prüf-ID */
export function stabil(x) {
  if (Array.isArray(x)) return `[${x.map(stabil).join(",")}]`;
  if (x && typeof x === "object") return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${stabil(x[k])}`).join(",")}}`;
  return JSON.stringify(x);
}

/** Prüf-ID: 16 Hex-Zeichen in Vierergruppen, z. B. „3F2A-91C0-…“ */
export function pruefIdFuer({ rechner, land, eingaben, stand = STAND_RECHENLOGIK }) {
  const h = createHash("sha256").update(stabil({ rechner, land, eingaben, stand }), "utf8").digest("hex").slice(0, 16).toUpperCase();
  return h.match(/.{4}/g).join("-");
}

/**
 * Neuberechnung auf dem Server.
 * @returns {{ rechner, titel, land, eingaben, roh, ergebnis, pruefId, stand, vorgangTyp }}
 *   roh: vollständiges Rechnerergebnis (nur für Tests/Vorgang, wird nicht gespeichert)
 *   ergebnis: Zusammenfassung für die Berichtsseite (Kennzahlen, Rechenweg, Tabellen, Hinweise)
 */
export function neuRechnen({ rechner, eingaben, land }) {
  const def = rechnerVon(rechner);
  const l = landPruefen(land);
  const e = eingabenPruefen(def.regeln, eingaben);
  def.landPruefen(e, l);
  const eingabenNorm = rechner === "flaechencheck" ? { ...e, land: l } : def.ohneRegion ? { ...e } : { ...e, regionId: e.regionId ?? standardRegion(l) };
  if (def.geldwerte && laenderSperre(l)) throw new PlattformFehler(422, `Für ${LAND_NAME[l]} ist dieser Bericht noch nicht verfügbar – die Rechenlogik wird gerade fachlich geprüft.`, "land_gesperrt");
  const roh = def.rechne(eingabenNorm, l);
  const zusammenfassung = def.zusammenfassen(roh, eingabenNorm, l);
  return {
    rechner,
    titel: def.titel,
    land: l,
    eingaben: eingabenNorm,
    roh,
    ergebnis: { ...zusammenfassung, sperre: roh.sperre ? { titel: roh.sperre.titel, text: roh.sperre.text } : null },
    pruefId: pruefIdFuer({ rechner, land: l, eingaben: eingabenNorm }),
    stand: STAND_RECHENLOGIK,
    vorgangTyp: def.vorgangTyp,
  };
}
// /api/rechner/bericht – Bericht-Baustein (Welle 2, Paket B4)
//
//   GET   → { ok, versand, modus, text }  Darf ein Bericht angefordert werden? (Oberfläche blendet das Formular sonst aus)
//   POST  { rechner, eingaben, land, kontakt: { vorname, nachname, email, telefon? }, einwilligungen?, herkunft?, website? }
//         → { ok, versand, hinweis }   Es entsteht noch KEIN Vorgang und KEIN Bericht (erst nach Double-Opt-in).
//
// Positivliste (4 Rechner), Eingabeprüfung und Neuberechnung: src/lib/bericht/neuRechnen.js – ein mitgeschicktes
// Ergebnis wird ignoriert. Rate-Limit über route() („anfrage“), Honeypot-Feld „website“, Body höchstens 8 KB.
// Personendaten stehen nie in Logs oder Fehlermeldungen dieser Route.

import { route, basisUrl } from "@/lib/plattform/server/route";
import { berichtAnfordern } from "@/lib/bericht/dienst";
import { versandStatus } from "@/lib/bericht/versand";

export const GET = route({ auth: false }, async () => ({ ok: true, ...versandStatus() }));

export const POST = route({ auth: false, limit: "anfrage", maxBytes: 8 * 1024 }, async ({ request, body }) => {
  const { rechner, eingaben, land, kontakt, einwilligungen, herkunft, website } = body; // bewusst nur diese Felder
  return berichtAnfordern({ body: { rechner, eingaben, land, kontakt, einwilligungen, herkunft, website }, basisUrl: basisUrl(request) });
});
// src/lib/bericht/gewerbestrom.js – Bericht-Baustein für den Rechnungs-Check Gewerbestrom (Welle 3, Paket B5)
//
// Feldregeln (Positivliste der Eingaben) und Zusammenfassung für die Berichtsseite. Eingebunden in
// src/lib/bericht/neuRechnen.js (RECHNER.gewerbestrom). Rechnet nicht selbst – nur gewerbestromCheck().
// Nur Deutschland (AT nach SNE-VO 2027 und CH in Vorbereitung).
// Der Lastgang verlässt den Browser nie: übermittelt werden nur Jahresverbrauch, Spitzenleistung und der
// daraus im Browser berechnete Profilfaktor (eine Zahl zwischen 0,5 und 1,5).

import { fmt, fmtEur } from "@/lib/rechner/annahmen";
import { BUNDESLAENDER, KAV_GRUPPEN, LASTPROFILE, NETZ_MODI, PREISARTEN, SPANNUNGEN, STUFEN, gewerbestromCheck } from "@/lib/rechner/gewerbestrom";

const ct = (x, s = 2) => `${fmt(x, s)} ct/kWh`;
const monatText = (iso) => {
  if (!iso) return "–";
  const [j, m] = iso.split("-").map(Number);
  return `${["Jan.", "Feb.", "März", "Apr.", "Mai", "Juni", "Juli", "Aug.", "Sept.", "Okt.", "Nov.", "Dez."][m - 1]} ${j}`;
};
const label = (liste, id) => liste.find((x) => x.id === id)?.label || id;
const ids = (liste) => liste.map((x) => x.id);

/** Feldregeln im Format von neuRechnen.js (zahl/wahl/bool werden dort gebaut und übergeben). */
export function regelnGewerbestrom({ zahl, wahl, jaNein }) {
  return {
    verbrauchMwh: zahl(1, 200000),
    leistungKw: zahl(0, 100000),
    spannung: wahl(ids(SPANNUNGEN)),
    preisArt: wahl(ids(PREISARTEN)),
    arbeitspreisCt: zahl(0.5, 150),
    grundpreisEurMonat: zahl(0, 10000),
    netzModus: wahl(ids(NETZ_MODI)),
    netzCt: zahl(0, 50),
    netzFixEurJahr: zahl(0, 5e6),
    kav: wahl(ids(KAV_GRUPPEN)),
    gemeinde: wahl(["bis25", "bis100", "bis500", "ueber500"]),
    produzierend: jaNein(),
    gruppeC: jaNein(),
    lastprofil: wahl(ids(LASTPROFILE)),
    profilFaktor: zahl(0.5, 1.5),
    bundesland: wahl(ids(BUNDESLAENDER)),
  };
}

/** Urteil als Satz (deutsch, für Bericht und Rechner). */
export function urteilText(r) {
  const s = r.spanne;
  switch (r.urteil.id) {
    case "marktgerecht":
      return `Ihr Energieanteil von ${ct(r.energie.ct)} liegt in der üblichen Spanne von ${ct(s.min)} bis ${ct(s.max)} (Börsenwert plus üblicher Lieferantenaufschlag). Ein Wechsel lohnt sich allein wegen des Preises kaum – prüfen Sie Laufzeit und Kündigungsfrist.`;
    case "guenstig":
      return `Ihr Energieanteil von ${ct(r.energie.ct)} liegt unter der üblichen Spanne (ab ${ct(s.min)}). Das kann ein früh abgeschlossener Vertrag sein – prüfen Sie aber, ob alle Bestandteile richtig eingetragen sind und wann der Vertrag endet.`;
    case "etwas_ueber":
      return `Ihr Energieanteil von ${ct(r.energie.ct)} liegt etwas über der üblichen Spanne (bis ${ct(s.max)}). Ein Vergleichsangebot zum nächsten Kündigungstermin kann sich lohnen.`;
    case "deutlich_ueber":
      return `Ihr Energieanteil von ${ct(r.energie.ct)} liegt deutlich über der üblichen Spanne (bis ${ct(s.max)}). Rechnerisch sind das ${fmtEur(r.differenz.minEur)} bis ${fmtEur(r.differenz.maxEur)} pro Jahr über dem Marktniveau – mit Blick auf Ihren Kündigungstermin lohnt sich ein Vergleich.`;
    case "offen":
      return "Ihr Arbeitspreis enthält das Netzentgelt. Ohne den Wert aus Ihrer Rechnung lässt sich der Energieanteil nicht vom Netzentgelt trennen – tragen Sie Netz-Arbeitspreis und Fixkosten aus der Rechnung ein.";
    default:
      return "Nach Abzug der amtlichen Bestandteile und des Netzentgelts bleibt kein Energieanteil übrig. Bitte prüfen Sie, ob der Arbeitspreis netto und ohne Umsatzsteuer eingetragen ist.";
  }
}

// src/lib/bericht/dienst.js
//
// Bericht-Baustein (Welle 2, Paket B4): Ablauf Anfordern → Double-Opt-in → Bericht. Nur serverseitig.
//
//  1. anfordern: Versand erlaubt? (sonst 503 „Berichtsversand startet mit dem Livegang.“ – ohne Personendaten
//     anzunehmen) → Neuberechnung (Positivliste, Eingabeprüfung) → Kontakt prüfen (Telefon freiwillig) →
//     Protokoll art "einwilligung" zweck "bericht" → Speichern (nur Token-Hash) + Bestätigungs-Mail.
//     Es entsteht KEIN Vorgang und KEIN Bericht.
//  2. bestaetigen (POST vom Knopf der Bestätigungsseite, nie per GET): Protokoll art "doi" zweck "bericht"
//     (ohne Personendaten, B3-Vertrag) → erst DANN backend.anfrageAnlegen (typ aus dem Rechner, Land,
//     strukturierte Rechnerdaten, die freiwilligen Häkchen) → Bericht 30 Tage abrufbar.
//  3. lesen: Bericht ohne Personendaten; abgelaufen → 410.
//
// Abhängigkeiten sind injizierbar (Tests); Standard: aktive Backends.

import { PlattformFehler } from "@/lib/plattform/fehler";
import { backend } from "@/lib/plattform/backend";
import { berichtBackend } from "@/lib/plattform/backend/bericht";
import { protokollAnhaengen } from "@/lib/plattform/backend/leadkette";
import { herkunftBereinigen } from "@/lib/gruppe/kanal";
import { RECHNER, neuRechnen } from "./neuRechnen";
import { annahmenbuchFuer } from "./annahmenbuch";
import { BESTAETIGUNG_STUNDEN, berichtBis, bestaetigungBis, tokenErzeugen, tokenHash } from "./token";
import { VERSAND_AUS_TEXT, bestaetigungsMail, versandErlaubt } from "./versand";
import { einwilligungenPruefen, kontaktPruefen, sha256 } from "./anforderung";
import { ANFORDERUNG, BERICHT_TEXT_VERSION, DOI } from "./texte";
import { berichtZaehlen } from "./zaehler";

const standard = (d = {}) => ({
  bericht: d.bericht || berichtBackend(),
  anfrage: d.anfrage || backend(),
  kette: d.kette || { protokollAnhaengen },
  versandErlaubt: d.versandErlaubt || (() => versandErlaubt()),
  jetzt: d.jetzt || (() => new Date()),
});

const objekt = (x) => (x && typeof x === "object" && !Array.isArray(x) ? x : {});
export const ANTWORT_ANGEFORDERT = `Fast geschafft: Wir haben Ihnen einen Bestätigungslink geschickt. Bitte öffnen Sie ihn innerhalb von ${BESTAETIGUNG_STUNDEN} Stunden – erst dann erstellen wir den Bericht.`;

/** POST /api/rechner/bericht */
export async function berichtAnfordern({ body, basisUrl }, deps) {
  const b = objekt(body);
  const merkmale = { rechner: b.rechner, land: typeof b.land === "string" ? b.land.toUpperCase() : "" };
  if (b.website) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    return { ok: true, versand: true, hinweis: ANTWORT_ANGEFORDERT }; // Honeypot: still verwerfen
  }
  const d = standard(deps);
  if (!d.versandErlaubt()) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw new PlattformFehler(503, VERSAND_AUS_TEXT, "versand_aus");
  }
  try {
    // Die Route übergibt body.ergebnis o. Ä. nie weiter – gerechnet wird ausschließlich hier.
    const r = neuRechnen({ rechner: b.rechner, eingaben: b.eingaben, land: b.land });
    const kontakt = kontaktPruefen(b.kontakt);
    const am = d.jetzt();
    const einwilligungen = einwilligungenPruefen(b.einwilligungen, { telefon: kontakt.telefon, am: am.toISOString() });
    const { kanal } = herkunftBereinigen(objekt(b.herkunft));
    const annahmen = annahmenbuchFuer(r.rechner, r.eingaben);
    const { token, hash } = tokenErzeugen();
    const link = `${String(basisUrl || "").replace(/\/$/, "")}/bericht/${token}`;

    await d.kette.protokollAnhaengen({
      email: kontakt.email,
      art: "einwilligung",
      zweck: "bericht",
      textId: ANFORDERUNG.textId,
      textVersion: BERICHT_TEXT_VERSION,
      textHash: sha256(ANFORDERUNG.text),
      kanal: "web_formular",
      land: r.land,
      zeit: am.toISOString(),
    });
    await d.bericht.berichtAnlegen({
      tokenHash: hash,
      rechner: r.rechner,
      land: r.land,
      eingaben: r.eingaben,
      ergebnis: { titel: r.titel, ...r.ergebnis, annahmen },
      pruefId: r.pruefId,
      stand: r.stand,
      ablauf: bestaetigungBis(am),
      kontakt,
      einwilligungen,
      kanal,
      mail: bestaetigungsMail({ rechnerTitel: r.titel, link, stunden: BESTAETIGUNG_STUNDEN }),
    });
    berichtZaehlen({ rechner: r.rechner, land: r.land, ereignis: "angefordert" });
    return { ok: true, versand: true, hinweis: ANTWORT_ANGEFORDERT };
  } catch (e) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw e;
  }
}

/** Strukturierte Rechnerdaten für den Vorgang (keine Personendaten) */
export function vorgangDaten(e) {
  const ein = objekt(e.eingaben);
  return {
    quelle: `bericht_${e.rechner}`,
    land: e.land,
    ...(Number.isFinite(ein.ha) ? { ha: ein.ha } : {}),
    ...(ein.regionId ? { regionId: ein.regionId } : {}),
    ...(e.rechner === "flaechencheck" && ein.nutzung ? { nutzung: ein.nutzung } : {}),
    bericht: {
      rechner: e.rechner,
      pruefId: e.pruefId,
      stand: e.stand,
      kennzahlen: (e.ergebnis?.kennzahlen || []).slice(0, 12).map((k) => `${k.label}: ${k.wert}${k.zusatz ? ` (${k.zusatz})` : ""}`),
    },
    eingaben: ein,
  };
}

/** POST /api/rechner/bericht/bestaetigen { token } */
export async function berichtBestaetigen({ token, ip = "" }, deps) {
  const hash = tokenHash(token);
  if (!hash) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  const d = standard(deps);
  const start = await d.bericht.berichtBestaetigungBeginnen({ tokenHash: hash, jetztMs: d.jetzt().getTime() });
  if (!start || start.zustand === null) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  if (start.zustand === "abgelaufen") throw new PlattformFehler(410, "Dieser Link ist abgelaufen. Bitte fordern Sie den Bericht im Rechner neu an.", "abgelaufen");
  if (start.zustand === "bestaetigt") return { ok: true, bereits: true };
  if (start.zustand === "in_bestaetigung") throw new PlattformFehler(409, "Die Bestätigung läuft bereits – bitte laden Sie die Seite in einem Moment neu.", "konflikt");
  const e = start.eintrag;
  try {
    await d.kette.protokollAnhaengen({
      email: e.kontakt.email,
      art: "doi",
      zweck: "bericht",
      textId: DOI.textId,
      textVersion: BERICHT_TEXT_VERSION,
      textHash: sha256(DOI.text),
      kanal: "doi_link",
      land: e.land,
    });
    const anfrage = await d.anfrage.anfrageAnlegen({
      typ: RECHNER[e.rechner].vorgangTyp,
      kontakt: { ...e.kontakt, land: e.land },
      daten: vorgangDaten(e),
      herkunft: { kanal: e.kanal || "Direkt" },
      ip,
      einwilligungText: ANFORDERUNG.hinweis,
      hinweis: { id: "hinweis_bericht", version: BERICHT_TEXT_VERSION, rechtsgrundlage: "Art. 6 Abs. 1 lit. b DSGVO", textHash: sha256(ANFORDERUNG.hinweis) },
      einwilligungen: Array.isArray(e.einwilligungen) ? e.einwilligungen : [],
      nutzer: null,
    });
    await d.bericht.berichtBestaetigungAbschliessen({ tokenHash: hash, vorgangId: anfrage.id, ablauf: berichtBis(d.jetzt()), jetztMs: d.jetzt().getTime() });
    berichtZaehlen({ rechner: e.rechner, land: e.land, ereignis: "bestaetigt" });
    return { ok: true, bereits: false };
  } catch (err) {
    await d.bericht.berichtBestaetigungZuruecksetzen({ tokenHash: hash }).catch(() => {});
    berichtZaehlen({ rechner: e.rechner, land: e.land, ereignis: "abgelehnt" });
    throw err;
  }
}

/** Für die Seite /bericht/[token] und GET der Bestätigungs-API: { zustand, bericht? } – nie Personendaten */
export async function berichtLesen({ token }, deps) {
  const hash = tokenHash(token);
  if (!hash) return { zustand: null };
  const d = { bericht: deps?.bericht || berichtBackend(), jetzt: deps?.jetzt || (() => new Date()) };
  return d.bericht.berichtLesen({ tokenHash: hash, jetztMs: d.jetzt().getTime() });
}
// src/lib/bericht/texte.js
//
// Texte des Bericht-Bausteins (Welle 2, Paket B4).
//
// ┌──────────────────────────────────────────────────────────────────────────────────────────────┐
// │ ENTWURF · Prüfung Rechtsabteilung. Alle Hinweis- und Haftungstexte hier sind bestmöglich      │
// │ formuliert, aber nicht freigegeben. Jede Textänderung → BERICHT_TEXT_VERSION erhöhen (der     │
// │ SHA-256 des Wortlauts steht im Einwilligungsprotokoll).                                        │
// └──────────────────────────────────────────────────────────────────────────────────────────────┘
//
// Rechtliche Linie (zu prüfen durch die Rechtsabteilung):
//  - Der Bericht ist eine angeforderte Leistung (Art. 6 Abs. 1 lit. b DSGVO). Werbung ist er nicht.
//  - Double-Opt-in, weil die E-Mail-Adresse nicht geprüft ist (Nachweis, dass die Inhaberin/der Inhaber
//    den Bericht wirklich wollte). Protokoll: Eintrag art "einwilligung" bei der Anforderung, art "doi" bei der
//    Bestätigung, zweck "bericht" (src/lib/plattform/backend/leadkette.js, Paket B3).
//  - Newsletter und Werbeanruf NUR über die getrennten, nicht vorbelegten Häkchen aus src/lib/anfrage/hinweise.js.
//  - Mit der Bestätigung entsteht ein Vorgang beim Team (transparent im Formular gesagt).

export const BERICHT_TEXT_VERSION = "ENTWURF-2026-10-03";
export const KENNZEICHNUNG_RECHT = "Entwurf · Prüfung Rechtsabteilung";

/** Wortlaut beim Absenden (Hash → Protokoll art "einwilligung", zweck "bericht") */
export const ANFORDERUNG = Object.freeze({
  textId: "bericht_anforderung",
  text: "Bitte senden Sie mir einen Bestätigungslink für den Bericht zu diesem Ergebnis an meine E-Mail-Adresse.",
  hinweis:
    "Wir nutzen Ihren Namen und Ihre E-Mail-Adresse, um Ihnen den Bericht bereitzustellen. Nach Ihrer Bestätigung legen wir zu diesem Ergebnis eine Anfrage bei unserem Team an; wir können Sie dazu einmal persönlich ansprechen. Ohne Bestätigung löschen wir Ihre Angaben nach 48 Stunden.",
  verweisVor: "Einzelheiten und Ihre Rechte finden Sie in der",
  verweisLink: "Datenschutzerklärung",
});

/** Wortlaut auf der Bestätigungsseite (Hash → Protokoll art "doi", zweck "bericht") */
export const DOI = Object.freeze({
  textId: "bericht_doi",
  titel: "Bericht bestätigen",
  text: "Ja, ich habe diesen Bericht angefordert und bestätige meine E-Mail-Adresse.",
  knopf: "Bestätigen und Bericht öffnen",
